function s(v) { return String(v == null ? '' : v).trim(); }
function nz(x) { return s(x).toLowerCase().replace(/[^a-z0-9]/g, ''); }
const invRaw = $('Read INVESTORS').all().map(function (i) { return i.json; });
const pipe = $input.all().map(function (i) { return i.json; });

// every amount in the cheque cell, INR Cr (USD at 85)
function chequeRange(txt) { const t = s(txt).replace(/,/g, '').toLowerCase(); if (!t) { return null; }
  const usd = /\$|usd/.test(t); const re = /(\d+(?:\.\d+)?)\s*(crores?|cr|million|mn|m|k|lakhs?|lacs?|l\b)?(?![a-z])/g;
  const tok = []; let m; while ((m = re.exec(t)) !== null) { tok.push({ v: parseFloat(m[1]), u: m[2] || '' }); }
  if (!tok.length) { return null; }
  for (let i = tok.length - 2; i >= 0; i--) { if (!tok[i].u && tok[i + 1].u) { tok[i].u = tok[i + 1].u; } }
  const vals = [];
  for (const k of tok) { const u = k.u || (usd ? 'm' : 'cr'); let cr;
    if (/^cr/.test(u)) { cr = k.v; } else if (/^la|^l$/.test(u)) { cr = k.v / 100; }
    else if (u === 'k') { cr = usd ? k.v * 0.0085 : k.v / 10000; } else { cr = usd ? k.v * 8.5 : k.v / 10; }
    if (cr > 0) { vals.push(cr); } }
  if (!vals.length) { return null; }
  let lo = Math.min.apply(null, vals), hi = Math.max.apply(null, vals);
  if (vals.length === 1 && /up\s*to|upto|\bmax/.test(t)) { lo = 0; }
  return [Math.round(lo * 100) / 100, Math.round(hi * 100) / 100]; }

const ORG = /\b(ventures?|venture|capital|partners?|fund|funds|vc|angels?|network|invest(ments?|or|ors)?|group|family|office|advisors?|ltd|llp|limited|holdings?|labs?|foundation|accelerator|collective|equity|growth|finserv|financial|bank|securities|asset|trust|syndicate|club|incubator|unicorns?|catalysts?|corp(oration)?|industries|enterprises?|debt|nabard|health|global|tech|india|x|seed|studio|associates|alternate|wealth)\b|\.vc|&/i;
const NETWORK = /angel|network|syndicate|\bipv\b|inflection point|venture catalysts|\bfaad\b|letsventure|lets venture|\bian\b|indian angel|hem angels|campus angels|keiretsu|lead angels|mumbai angels|\bclub\b/i;
const FAMILY = /family office|family\b|\bfo\b/i;
const DEBT = /\bdebt\b|blacksoil|northern arc|caspian|debtworks|coin-?age|alteria|trifecta|stride ventures/i;
const CORP = /bajaj|wipro|flipkart|info edge|hitachi|tdk|lockheed|l'?oreal|tvs capital|baldota|sar group|\bsig group\b|nabard|redesign health|reliance|tata|mahindra|infosys|samsung|intel capital|qualcomm/i;

const byName = {};
for (const r of invRaw) { const n = s(r.investor); if (!n) { continue; } const k = nz(n); if (!byName[k]) { byName[k] = []; } byName[k].push(r); }
const sent = {}, queued = {};
for (const p of pipe) { const k = nz(p.investor); if (s(p.deal_shared).toLowerCase() === 'yes') { sent[k] = (sent[k] || 0) + 1; }
  else if (s(p.pause).toLowerCase() !== 'yes') { queued[k] = (queued[k] || 0) + 1; } }

const rows = [];
for (const k of Object.keys(byName)) {
  const rs = byName[k]; const pick = rs.filter(function (r) { return s(r.cheque_inr_cr) !== ''; })[0] || rs[0];
  const name = s(pick.investor); const contact = s(pick.contact_person); const cheque = s(pick.cheque_inr_cr);
  const sector = s(pick.sector); const stage = s(pick.stage);
  const dnc = rs.some(function (r) { return s(r.do_not_contact).toLowerCase() === 'yes'; });
  const rng = chequeRange(cheque);
  const blob = name + ' ' + sector + ' ' + stage + ' ' + cheque;
  // individual: the name reads like a person - no firm words, 1-3 words, or the name is the contact person
  const words = name.replace(/\(.*?\)/g, '').trim().split(/\s+/).filter(Boolean);
  const personLike = !ORG.test(name.replace(/\(.*?\)/g, '')) && words.length >= 1 && words.length <= 3 && /^[A-Z][a-z]/.test(words[0]) && (words.length >= 2 || (contact && nz(contact).indexOf(nz(name)) >= 0));
  const isIndividual = personLike || (contact && nz(contact) === nz(name));
  const isNetwork = NETWORK.test(name) || /angel network|syndicate/i.test(blob);
  const flags = [];
  if (FAMILY.test(name)) { flags.push('Family office'); } if (DEBT.test(blob)) { flags.push('Debt'); } if (CORP.test(name)) { flags.push('Corporate VC'); }
  let bucket;
  if (isIndividual) { bucket = '1. Individual angel'; }
  else if (isNetwork) { bucket = '2. Angel network / syndicate'; }
  else if (!rng) { bucket = '7. Cheque not stated'; }
  else { const mid = (rng[0] + rng[1]) / 2;
    if (rng[1] <= 2) { bucket = '3. Micro VC / pre-seed VC'; }
    else if (mid <= 5) { bucket = '4. Seed fund'; }
    else if (mid <= 25) { bucket = '5. Institutional VC'; }
    else { bucket = '6. Large VC / growth (above 25 Cr)'; } }
  rows.push({ investor: name, contact: contact, bucket: bucket, flags: flags.join(', '), cheque_text: cheque,
    cheque_min_cr: rng ? rng[0] : null, cheque_max_cr: rng ? rng[1] : null, stage: stage.slice(0, 50), sector: sector.slice(0, 70),
    do_not_contact: dnc ? 'Yes' : '', sheet_rows: rs.length, deals_sent: sent[k] || 0, deals_queued: queued[k] || 0 });
}
rows.sort(function (a, b) { return a.bucket.localeCompare(b.bucket) || a.investor.localeCompare(b.investor); });
const summary = {};
for (const r of rows) { const b = r.bucket; if (!summary[b]) { summary[b] = { all: 0, contactable: 0, dnc: 0, sent: 0, queued: 0 }; }
  summary[b].all++; if (r.do_not_contact) { summary[b].dnc++; } else { summary[b].contactable++; } summary[b].sent += r.deals_sent; summary[b].queued += r.deals_queued; }
const raw = invRaw.map(function (r) { return { row: r.row_number, investor: s(r.investor), contact_person: s(r.contact_person), email: s(r.email), cc: s(r.cc), sector: s(r.sector), stage: s(r.stage), cheque_inr_cr: s(r.cheque_inr_cr), do_not_contact: s(r.do_not_contact) }; });
return [{ json: { investor_rows_in_sheet: invRaw.length, distinct_investors: rows.length, summary: summary, investors: rows, raw: raw } }];
